WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessions_web_events AS (SELECT id, page, event_time, duration_sec, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT burst_id, CASE WHEN duration_sec >= 386 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, ROUND(AVG(burst_id), 2) AS avg_burst_id, BIT_AND(duration_sec) AS duration_sec_bit_and, SUM(burst_id) FILTER (WHERE page = '/cart') AS cart_total_burst_id, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT_IF(page = '/product') AS product_events, COUNT(*) FILTER (WHERE page = '/search') AS search_rows FROM sessions_web_events GROUP BY 1, 2 HAVING ROUND(AVG(burst_id), 2) > 0 ORDER BY avg_duration_sec DESC;
